import pandas as pd
def events():
    rows=[]
    for t,d in RAW.items():
        for tm,s in d.items():
            for x in s.split():
                p=x.endswith('p'); x=x.rstrip('p')
                rows.append(dict(t=t,date=pd.Timestamp('20'+x[:2]+'-'+x[2:4]+'-'+x[4:6]),timing=tm,prelim=p))
    return pd.DataFrame(rows).sort_values(['t','date']).reset_index(drop=True)
